export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[];
  draft?: boolean;
  [key: string]: unknown;
}

export interface Page {
  frontmatter: Frontmatter;
  content: string;
  slug: string;
  sourcePath: string;
  outputPath: string;
  html: string;
}

import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const decoder = new TextDecoder();

export function readTextFile(fpath: string): string {
  return fs.readFileSync(fpath, "utf-8");
}

export function writeTextFile(fpath: string, data: string): void {
  fs.mkdirSync(path.dirname(fpath), { recursive: true });
  fs.writeFileSync(fpath, data, "utf-8");
}

export function copyFile(src: string, dest: string): void {
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.copyFileSync(src, dest);
}

export function walkDir(
  dir: string,
  cb: (fpath: string, relative: string) => void
): void {
  if (!fs.existsSync(dir)) return;
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      walkDir(full, cb);
    } else if (entry.isFile()) {
      cb(full, path.relative(dir, full));
    }
  }
}

export function normalizeMarkdownPath(relative: string): string {
  const parsed = path.parse(relative);
  if (parsed.name === "index") {
    return path.join(parsed.dir, "index.html");
  }
  return path.join(parsed.dir, parsed.name, "index.html");
}

export function inDevMode(params: URLSearchParams): boolean {
  return params.has("devmode");
}

import { marked, Renderer } from "marked";
import hljs from "highlight.js";
import matter from "gray-matter";
import type { Frontmatter, Page } from "./types.js";
import { normalizeMarkdownPath } from "./utils.js";

const renderer = new Renderer();
const baseCode = renderer.code.bind(renderer);

renderer.code = function (token: { text: string; lang?: string; escaped?: boolean }): string {
  const { text, lang } = token;
  if (lang && hljs.getLanguage(lang)) {
    const highlighted = hljs.highlight(text, { language: lang }).value;
    return `<pre><code class="hljs language-${lang}">${highlighted}</code></pre>\n`;
  }
  return `<pre><code>${text}</code></pre>\n`;
};

marked.use({ renderer });

export function parseMarkdown(
  raw: string,
  sourcePath: string
): Pick<Page, "frontmatter" | "content" | "slug" | "sourcePath"> {
  const { data, content: mdBody } = matter(raw);

  const frontmatter: Frontmatter = {
    title: data.title ?? "Untitled",
    date: data.date ? String(data.date) : undefined,
    tags: data.tags ?? [],
    draft: data.draft ?? false,
    ...data,
  };

  if (!Array.isArray(frontmatter.tags)) {
    frontmatter.tags = [];
  }

  const htmlContent = marked.parse(mdBody, { async: false }) as string;

  const slug = normalizeMarkdownPath(path.parse(sourcePath).dir + "/" + path.parse(sourcePath).name)
    .replace(/\/index\.html$/, "")
    .replace(/^\//, "");

  return {
    frontmatter,
    content: htmlContent,
    slug,
    sourcePath,
  };
}

export function getPublishedPages(pages: Page[]): Page[] {
  return pages.filter((p) => !p.frontmatter.draft);
}

export function sortByDate(pages: Page[]): Page[] {
  return [...pages].sort((a, b) => {
    const da = a.frontmatter.date ? new Date(a.frontmatter.date).getTime() : 0;
    const db = b.frontmatter.date ? new Date(b.frontmatter.date).getTime() : 0;
    return db - da;
  });
}

import Handlebars from "handlebars";
import fs from "node:fs";
import path from "node:path";

export interface TemplateContext {
  [key: string]: unknown;
  page?: unknown;
  pages?: unknown[];
  site?: unknown;
  tags?: unknown;
}

export function loadPartials(partialsDir: string): void {
  if (!fs.existsSync(partialsDir)) return;
  const entries = fs.readdirSync(partialsDir);
  for (const entry of entries) {
    const fpath = path.join(partialsDir, entry);
    if (!fpath.endsWith(".hbs")) continue;
    const name = path.basename(entry, ".hbs");
    const src = fs.readFileSync(fpath, "utf-8");
    Handlebars.registerPartial(name, src);
  }
}

export function compileTemplate(templateDir: string, templateName: string): HandlebarsTemplateDelegate {
  const fpath = path.join(templateDir, `${templateName}.hbs`);
  if (!fs.existsSync(fpath)) {
    throw new Error(`Template not found: ${fpath}`);
  }
  const src = fs.readFileSync(fpath, "utf-8");
  return Handlebars.compile(src);
}

export function renderPage(
  content: string,
  layout: HandlebarsTemplateDelegate | null,
  template: HandlebarsTemplateDelegate,
  context: TemplateContext
): string {
  const body = template(context);
  if (layout) {
    return layout({ ...context, body });
  }
  return body;
}

export function compileLayout(templateDir: string, layoutName: string): HandlebarsTemplateDelegate | null {
  const fpath = path.join(templateDir, `${layoutName}.hbs`);
  if (!fs.existsSync(fpath)) return null;
  const src = fs.readFileSync(fpath, "utf-8");
  return Handlebars.compile(src);
}

import type { Page } from "./types.js";

export interface TagInfo {
  tag: string;
  count: number;
  pages: Page[];
}

export function buildTagIndex(pages: Page[]): Map<string, TagInfo> {
  const map = new Map<string, TagInfo>();
  for (const page of pages) {
    for (const tag of page.frontmatter.tags ?? []) {
      if (!map.has(tag)) {
        map.set(tag, { tag, count: 0, pages: [] });
      }
      const info = map.get(tag)!;
      info.count++;
      info.pages.push(page);
    }
  }
  return map;
}

export function generateTagPages(
  tags: Map<string, TagInfo>,
  pages: Page[],
  renderTagPage: (tag: TagInfo, allPages: Page[]) => string
): Map<string, string> {
  const result = new Map<string, string>();
  for (const [tag, info] of tags) {
    const html = renderTagPage(info, pages);
    result.set(`tags/${tag}/index.html`, html);
  }
  return result;
}

import { Feed } from "feed";
import type { Page } from "./types.js";

export interface RSSOptions {
  title: string;
  description: string;
  baseUrl: string;
  author?: string;
}

export function generateRSS(pages: Page[], options: RSSOptions): string {
  const feed = new Feed({
    title: options.title,
    description: options.description,
    id: options.baseUrl,
    link: options.baseUrl,
    language: "en",
    updated: pages.length > 0 ? new Date(pages[0].frontmatter.date ?? Date.now()) : new Date(),
    copyright: "",
    author: {
      name: options.author ?? options.title,
    },
  });

  for (const page of pages) {
    const url = `${options.baseUrl}/${page.slug}/`;
    feed.addItem({
      title: page.frontmatter.title,
      id: url,
      link: url,
      description: page.content,
      date: new Date(page.frontmatter.date ?? Date.now()),
    });
  }

  return feed.rss2();
}

import { compileLayout, compileTemplate, loadPartials, renderPage } from "./renderer.js";
import { buildTagIndex, generateTagPages } from "./tags.js";
import { generateRSS } from "./rss.js";
import { getPublishedPages, parseMarkdown, sortByDate } from "./parser.js";
import type { Page } from "./types.js";
import { copyFile, walkDir, writeTextFile, readTextFile } from "./utils.js";
import path from "node:path";
import fs from "node:fs";

export interface BuildOptions {
  source: string;
  templates: string;
  output: string;
  baseUrl: string;
  siteTitle: string;
  siteDescription: string;
  author?: string;
  includeDrafts: boolean;
}

export function build(options: BuildOptions): Page[] {
  const pages: Page[] = [];

  walkDir(options.source, (fpath, relative) => {
    if (!fpath.endsWith(".md")) return;
    const raw = readTextFile(fpath);
    const parsed = parseMarkdown(raw, relative);
    pages.push({
      ...parsed,
      outputPath: path.join(options.output, parsed.slug, "index.html"),
      html: "",
    });
  });

  const visible = options.includeDrafts ? pages : getPublishedPages(pages);
  const sorted = sortByDate(visible);

  loadPartials(path.join(options.templates, "partials"));

  const layout = compileLayout(options.templates, "layout");
  const pageTemplate = compileTemplate(options.templates, "page");
  const tagTemplate = compileTemplate(options.templates, "tag");
  const listingTemplate = compileTemplate(options.templates, "listing");

  const tags = buildTagIndex(sorted);

  const tagList = Array.from(tags.values()).map((t) => ({
    tag: t.tag,
    count: t.count,
  }));

  const siteContext = {
    title: options.siteTitle,
    description: options.siteDescription,
    baseUrl: options.baseUrl,
  };

  for (const page of sorted) {
    const ctx = {
      page: {
        ...page.frontmatter,
        content: page.content,
        slug: page.slug,
      },
      pages: sorted.map((p) => ({
        title: p.frontmatter.title,
        slug: p.slug,
        date: p.frontmatter.date,
        tags: p.frontmatter.tags,
      })),
      tags: tagList,
      site: siteContext,
    };
    page.html = renderPage(page.content, layout, pageTemplate, ctx);
    writeTextFile(page.outputPath, page.html);
  }

  const listingCtx = {
    pages: sorted.map((p) => ({
      title: p.frontmatter.title,
      slug: p.slug,
      date: p.frontmatter.date,
      tags: p.frontmatter.tags,
      content: p.content,
    })),
    tags: tagList,
    site: siteContext,
  };
  const listingHtml = renderPage("", layout, listingTemplate, listingCtx);
  writeTextFile(path.join(options.output, "index.html"), listingHtml);

  const tagPages = generateTagPages(tags, sorted, (tagInfo, allPages) => {
    const ctx = {
      tag: { tag: tagInfo.tag, count: tagInfo.count },
      pages: tagInfo.pages.map((p) => ({
        title: p.frontmatter.title,
        slug: p.slug,
        date: p.frontmatter.date,
        tags: p.frontmatter.tags,
      })),
      tags: tagList,
      site: siteContext,
    };
    if (layout) {
      return layout({ ...ctx, body: tagTemplate(ctx) });
    }
    return tagTemplate(ctx);
  });

  for (const [relPath, html] of tagPages) {
    writeTextFile(path.join(options.output, relPath), html);
  }

  const rssXml = generateRSS(sorted, {
    title: options.siteTitle,
    description: options.siteDescription,
    baseUrl: options.baseUrl,
    author: options.author,
  });
  writeTextFile(path.join(options.output, "feed.xml"), rssXml);

  walkDir(options.source, (fpath, relative) => {
    if (fpath.endsWith(".md")) return;
    copyFile(fpath, path.join(options.output, relative));
  });

  walkDir(options.templates, (fpath, relative) => {
    if (fpath.endsWith(".hbs")) return;
    copyFile(fpath, path.join(options.output, relative));
  });

  return sorted;
}

import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import { WebSocketServer, WebSocket } from "ws";
import chokidar from "chokidar";
import { build } from "./builder.js";

const RELOAD_SCRIPT = `
<script>
(function(){
  if(window.__ssgLiveReload)return;
  window.__ssgLiveReload=true;
  var ws=new WebSocket('ws://'+(location.host||location.hostname)+'/__livereload');
  ws.onmessage=function(e){if(e.data==='reload')location.reload();};
  ws.onclose=function(){setTimeout(function(){location.reload();},2000);};
})();
</script>
</body>`;

function injectReloadScript(html: string): string {
  if (html.includes("__ssgLiveReload")) return html;
  return html.replace(/<\/body>/i, RELOAD_SCRIPT);
}

const MIME: Record<string, string> = {
  ".html": "text/html",
  ".css": "text/css",
  ".js": "application/javascript",
  ".json": "application/json",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".svg": "image/svg+xml",
  ".xml": "application/xml",
  ".woff2": "font/woff2",
  ".ico": "image/x-icon",
};

export function startDevServer(
  outputDir: string,
  watchDirs: string[],
  port: number,
  rebuild: () => void
): http.Server {
  rebuild();

  const server = http.createServer((req, res) => {
    const url = new URL(req.url ?? "/", `http://localhost:${port}`);
    let fpath = path.join(outputDir, url.pathname);
    if (url.pathname === "/" || url.pathname.endsWith("/")) {
      fpath = path.join(fpath, "index.html");
    }

    const ext = path.extname(fpath).toLowerCase();
    const contentType = MIME[ext] ?? "application/octet-stream";

    try {
      const content = fs.readFileSync(fpath);
      res.writeHead(200, { "Content-Type": contentType });

      if (ext === ".html") {
        const html = injectReloadScript(content.toString("utf-8"));
        res.end(html);
      } else {
        res.end(content);
      }
    } catch {
      res.writeHead(404);
      res.end("Not found");
    }
  });

  const wss = new WebSocketServer({ server });
  const clients = new Set<WebSocket>();

  wss.on("connection", (ws, req) => {
    if (req.url === "/__livereload") {
      clients.add(ws);
      ws.on("close", () => clients.delete(ws));
    }
  });

  watchDirs.forEach((dir) => {
    if (!fs.existsSync(dir)) return;
    chokidar.watch(dir, { ignoreInitial: true }).on("all", () => {
      rebuild();
      for (const client of clients) {
        if (client.readyState === WebSocket.OPEN) {
          client.send("reload");
        }
      }
    });
  });

  server.listen(port);
  return server;
}

#!/usr/bin/env node
import { Command } from "commander";
import { build } from "./builder.js";
import { startDevServer } from "./server.js";

const program = new Command();

program
  .name("staticsite")
  .description("Static site generator")
  .version("1.0.0")
  .requiredOption("--source <dir>", "Source directory of markdown files")
  .requiredOption("--templates <dir>", "Template directory of handlebars files")
  .requiredOption("--output <dir>", "Output directory for generated HTML")
  .option("--base-url <url>", "Base URL for RSS feed", "http://localhost:3000")
  .option("--site-title <title>", "Site title", "My Site")
  .option("--site-description <desc>", "Site description", "A static site")
  .option("--author <name>", "Site author")
  .option("--dev", "Start dev server with live reload")
  .option("--port <port>", "Dev server port", "3000");

program.parse();

const opts = program.opts();

const buildOpts = {
  source: opts.source,
  templates: opts.templates,
  output: opts.output,
  baseUrl: opts.baseUrl,
  siteTitle: opts.siteTitle,
  siteDescription: opts.siteDescription,
  author: opts.author,
  includeDrafts: !!opts.dev,
};

if (opts.dev) {
  const port = parseInt(opts.port, 10);
  const server = startDevServer(
    opts.output,
    [opts.source, opts.templates],
    port,
    () => build(buildOpts)
  );
  console.log(`Dev server running at http://localhost:${port}`);
  console.log("Watching for changes...");
} else {
  build(buildOpts);
  console.log(`Site built to ${opts.output}`);
}

