import { describe, it, expect } from "vitest";
import { parseMarkdown, getPublishedPages, sortByDate } from "../src/parser.js";
import type { Page } from "../src/types.js";

describe("parseMarkdown", () => {
  it("parses title from frontmatter", () => {
    const md = `---
title: Hello World
---
Some content.`;

    const result = parseMarkdown(md, "hello.md");
    expect(result.frontmatter.title).toBe("Hello World");
  });

  it("parses date from frontmatter", () => {
    const md = `---
title: Test
date: 2024-01-15
---
Content`;

    const result = parseMarkdown(md, "test.md");
    expect(result.frontmatter.date).toBe("2024-01-15");
  });

  it("parses tags as array", () => {
    const md = `---
title: Tagged
tags:
  - typescript
  - nodejs
---
Content`;

    const result = parseMarkdown(md, "tagged.md");
    expect(result.frontmatter.tags).toEqual(["typescript", "nodejs"]);
  });

  it("parses draft flag", () => {
    const md = `---
title: Draft Post
draft: true
---
Secret stuff`;

    const result = parseMarkdown(md, "draft.md");
    expect(result.frontmatter.draft).toBe(true);
  });

  it("defaults draft to false when not set", () => {
    const md = `---
title: Published
---
Public`;

    const result = parseMarkdown(md, "pub.md");
    expect(result.frontmatter.draft).toBe(false);
  });

  it("defaults title to Untitled when missing", () => {
    const md = `---
tags: [a]
---
No title`;

    const result = parseMarkdown(md, "notitle.md");
    expect(result.frontmatter.title).toBe("Untitled");
  });

  it("converts markdown content to HTML", () => {
    const md = `---
title: MD Test
---
**bold** and *italic*`;

    const result = parseMarkdown(md, "mdtest.md");
    expect(result.content).toContain("<strong>bold</strong>");
    expect(result.content).toContain("<em>italic</em>");
  });

  it("generates slug from source path", () => {
    const md = `---
title: Deep
---
Content`;

    const result = parseMarkdown(md, "blog/deep.md");
    expect(result.slug).toBe("blog/deep");
  });

  it("handles index.md as directory index", () => {
    const md = `---
title: Index Page
---
Index`;

    const result = parseMarkdown(md, "index.md");
    expect(result.slug).toBe("");
  });

  it("handles code blocks with language", () => {
    const md = `---
title: Code
---
\`\`\`typescript
const x = 1;
\`\`\``;

    const result = parseMarkdown(md, "code.md");
    expect(result.content).toContain("<pre>");
    expect(result.content).toContain("<code");
    expect(result.content).toContain("language-typescript");
  });

  it("handles code blocks without language", () => {
    const md = `---
title: NoLang
---
\`\`\`
plain code
\`\`\``;

    const result = parseMarkdown(md, "nolang.md");
    expect(result.content).toContain("<code>plain code");
  });
});

describe("getPublishedPages", () => {
  it("filters out draft pages", () => {
    const pages: Page[] = [
      {
        frontmatter: { title: "A", draft: false },
        content: "",
        slug: "a",
        sourcePath: "a.md",
        outputPath: "",
        html: "",
      },
      {
        frontmatter: { title: "B", draft: true },
        content: "",
        slug: "b",
        sourcePath: "b.md",
        outputPath: "",
        html: "",
      },
    ];

    const result = getPublishedPages(pages);
    expect(result).toHaveLength(1);
    expect(result[0].frontmatter.title).toBe("A");
  });
});

describe("sortByDate", () => {
  it("sorts pages by date descending", () => {
    const pages: Page[] = [
      {
        frontmatter: { title: "Old", date: "2023-01-01" },
        content: "",
        slug: "old",
        sourcePath: "",
        outputPath: "",
        html: "",
      },
      {
        frontmatter: { title: "New", date: "2024-06-15" },
        content: "",
        slug: "new",
        sourcePath: "",
        outputPath: "",
        html: "",
      },
      {
        frontmatter: { title: "Mid", date: "2024-01-01" },
        content: "",
        slug: "mid",
        sourcePath: "",
        outputPath: "",
        html: "",
      },
    ];

    const sorted = sortByDate(pages);
    expect(sorted[0].frontmatter.title).toBe("New");
    expect(sorted[1].frontmatter.title).toBe("Mid");
    expect(sorted[2].frontmatter.title).toBe("Old");
  });
});

import { describe, it, expect, beforeEach } from "vitest";
import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import {
  loadPartials,
  compileTemplate,
  compileLayout,
  renderPage,
} from "../src/renderer.js";

describe("renderer", () => {
  let tmpDir: string;

  beforeEach(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "ssg-renderer-"));
  });

  describe("loadPartials", () => {
    it("loads and registers partials from a directory", () => {
      const partialsDir = path.join(tmpDir, "partials");
      fs.mkdirSync(partialsDir, { recursive: true });
      fs.writeFileSync(
        path.join(partialsDir, "header.hbs"),
        "<header>{{title}}</header>"
      );
      fs.writeFileSync(
        path.join(partialsDir, "footer.hbs"),
        "<footer>end</footer>"
      );

      loadPartials(partialsDir);

      const main = `{{> header}}{{> footer}}`;
      const Handlebars = await import("handlebars");
      const tmpl = Handlebars.default.compile(main);
      const result = tmpl({ title: "Hello" });
      expect(result).toContain("<header>Hello</header>");
      expect(result).toContain("<footer>end</footer>");
    });

    it("does nothing if partials directory does not exist", () => {
      expect(() =>
        loadPartials(path.join(tmpDir, "nonexistent"))
      ).not.toThrow();
    });
  });

  describe("compileTemplate and renderPage", () => {
    it("renders a simple template with context", () => {
      fs.writeFileSync(
        path.join(tmpDir, "page.hbs"),
        "<h1>{{page.title}}</h1><div>{{{page.content}}}</div>"
      );

      const template = compileTemplate(tmpDir, "page");
      const result = renderPage("", null, template, {
        page: { title: "Test", content: "<p>Body</p>" },
      });
      expect(result).toContain("<h1>Test</h1>");
      expect(result).toContain("<p>Body</p>");
    });

    it("renders with a layout", () => {
      fs.writeFileSync(
        path.join(tmpDir, "layout.hbs"),
        "<html><body>{{{body}}}</body></html>"
      );
      fs.writeFileSync(
        path.join(tmpDir, "page.hbs"),
        "<main>{{page.title}}</main>"
      );

      const layout = compileLayout(tmpDir, "layout");
      const template = compileTemplate(tmpDir, "page");
      const result = renderPage("", layout, template, {
        page: { title: "Layered" },
      });
      expect(result).toContain("<html>");
      expect(result).toContain("<main>Layered</main>");
      expect(result).toContain("</html>");
    });

    it("renders without layout when layout is null", () => {
      fs.writeFileSync(
        path.join(tmpDir, "page.hbs"),
        "<p>{{page.title}}</p>"
      );

      const template = compileTemplate(tmpDir, "page");
      const result = renderPage("", null, template, {
        page: { title: "Solo" },
      });
      expect(result).toBe("<p>Solo</p>");
    });

    it("throws when template not found", () => {
      expect(() => compileTemplate(tmpDir, "missing")).toThrow(
        /Template not found/
      );
    });

    it("returns null when layout not found", () => {
      const layout = compileLayout(tmpDir, "nonexistent");
      expect(layout).toBeNull();
    });
  });

  describe("context propagation", () => {
    it("passes site context to template", () => {
      fs.writeFileSync(
        path.join(tmpDir, "page.hbs"),
        "<title>{{site.title}}</title><p>{{page.title}}</p>"
      );

      const template = compileTemplate(tmpDir, "page");
      const result = renderPage("", null, template, {
        site: { title: "My Site" },
        page: { title: "Post" },
      });

      expect(result).toContain("<title>My Site</title>");
      expect(result).toContain("<p>Post</p>");
    });

    it("passes pages list for navigation", () => {
      fs.writeFileSync(
        path.join(tmpDir, "page.hbs"),
        "{{#each pages}}<a href=\"/{{slug}}/\">{{title}}</a>{{/each}}"
      );

      const template = compileTemplate(tmpDir, "page");
      const result = renderPage("", null, template, {
        pages: [
          { title: "A", slug: "a" },
          { title: "B", slug: "b" },
        ],
      });

      expect(result).toContain('href="/a/"');
      expect(result).toContain('href="/b/"');
    });
  });
});

import { describe, it, expect } from "vitest";
import { buildTagIndex, generateTagPages } from "../src/tags.js";
import type { Page } from "../src/types.js";

const makePage = (
  title: string,
  tags: string[],
  slug: string = title.toLowerCase()
): Page => ({
  frontmatter: { title, tags },
  content: `<p>${title}</p>`,
  slug,
  sourcePath: `${slug}.md`,
  outputPath: `out/${slug}/index.html`,
  html: "",
});

describe("buildTagIndex", () => {
  it("builds index from pages with tags", () => {
    const pages = [
      makePage("Post 1", ["typescript", "node"]),
      makePage("Post 2", ["typescript"]),
      makePage("Post 3", ["css"]),
    ];

    const idx = buildTagIndex(pages);
    expect(idx.get("typescript")!.count).toBe(2);
    expect(idx.get("node")!.count).toBe(1);
    expect(idx.get("css")!.count).toBe(1);
  });

  it("handles pages with no tags", () => {
    const pages = [makePage("No Tags", [])];
    const idx = buildTagIndex(pages);
    expect(idx.size).toBe(0);
  });

  it("handles missing tags field", () => {
    const page: Page = {
      frontmatter: { title: "Missing Tags" },
      content: "",
      slug: "missing",
      sourcePath: "missing.md",
      outputPath: "",
      html: "",
    };
    const idx = buildTagIndex([page]);
    expect(idx.size).toBe(0);
  });

  it("includes page references in tag info", () => {
    const pages = [makePage("T1", ["rust"])];
    const idx = buildTagIndex(pages);
    const info = idx.get("rust")!;
    expect(info.pages).toHaveLength(1);
    expect(info.pages[0].frontmatter.title).toBe("T1");
  });
});

describe("generateTagPages", () => {
  it("generates HTML for each tag", () => {
    const pages = [
      makePage("A1", ["go"]),
      makePage("A2", ["python"]),
    ];
    const idx = buildTagIndex(pages);

    const renderTagPage = (info: ReturnType<typeof buildTagIndex> extends Map<string, infer T> ? T : never, _all: Page[]) =>
      `<h1>Tag: ${info.tag} (${info.count})</h1>`;

    const result = generateTagPages(idx, pages, renderTagPage);
    expect(result.size).toBe(2);
    expect(result.get("tags/go/index.html")).toContain("Tag: go (1)");
    expect(result.get("tags/python/index.html")).toContain("Tag: python (1)");
  });
});

